/**
 * SQL predicate matching `canViewProject` in `project-service`.
 *
 * Private to the repository layer. A `private` project is excluded for
 * `viewer` unless they are platform staff, an org admin or owner, the
 * project's lead, or a row in `project_members`. `org` and `public` projects
 * are never excluded. Passing no viewer leaves the query unfiltered so jobs
 * and other repository callers keep seeing every row.
 */
import { and, eq, isNull, ne, notInArray, or } from "drizzle-orm";
import { getDb, projectMembers, projects } from "@/server/db";
import { hasRoleAtLeast } from "@/types/member";
import { orgPredicate } from "./base-repository";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";
import type { Actor } from "@/types/member";

/**
 * `column NOT IN (private projects this viewer cannot see)`, or `undefined`
 * when the viewer can see every project.
 */
export function hiddenPrivateProjectPredicate(
  column: SQLiteColumn,
  viewer: Actor | undefined,
): SQL | undefined {
  if (viewer === undefined) return undefined;
  if (viewer.isPlatformStaff === true) return undefined;
  if (hasRoleAtLeast(viewer.role, "admin")) return undefined;

  const memberProjects = getDb()
    .select({ projectId: projectMembers.projectId })
    .from(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, viewer.orgId),
        eq(projectMembers.userId, viewer.userId),
      ),
    );

  const hidden = getDb()
    .select({ id: projects.id })
    .from(projects)
    .where(
      and(
        orgPredicate(projects.orgId, viewer.orgId),
        eq(projects.visibility, "private"),
        or(isNull(projects.leadId), ne(projects.leadId, viewer.userId)),
        notInArray(projects.id, memberProjects),
      ),
    );

  return notInArray(column, hidden);
}

