import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { hasRoleAtLeast } from "@/types/member";
import {
  NotFoundError,
  actorEnvelope,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";

import type { Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Whether `actor` may see `project`. `org` and `public` projects are visible
 * to every actor in the organization. A `private` project is visible only to
 * an admin or owner of its organization, platform staff, the project's lead,
 * or an explicit project member. Membership and lead are read from the
 * current row, so a change takes effect on the next call.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.isPlatformStaff === true) return true;
  if (
    actor.orgId === project.orgId &&
    hasRoleAtLeast(actor.role, "admin")
  ) {
    return true;
  }
  if (project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/** Hides a private project behind the same error as a missing row. */
async function assertProjectVisible(
  actor: Actor,
  project: Project,
  id: string,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", id);
  }
}

