/**
 * Comments on an issue in a private project the actor cannot see are
 * indistinguishable from a missing issue or comment. No write runs after this.
 */
async function assertIssueCommentVisible(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  entity: "Issue" | "Comment",
  id: string,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue === null) {
    if (entity === "Issue") throw new NotFoundError("Issue", id);
    return;
  }
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (project !== null && !(await canViewProject(actor, project))) {
    throw new NotFoundError(entity, id);
  }
}

