import { NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("privvis", "growth");
});

afterAll(() => {
  cleanup();
});

describe("private project visibility", () => {
  it("hides a private project from everyone except admin, owner, staff, lead and members", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Secret",
      slug: "secret",
      key: "SEC",
      description: null,
      visibility: "private",
      leadId: tenant.userIds.viewer,
      color: "#6366f1",
      targetDate: null,
    });

    const outsider = tenant.actors.member;
    expect(await projectService.canViewProject(outsider, project)).toBe(false);
    expect(await projectService.canViewProject(tenant.actors.admin, project)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.owner, project)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.viewer, project)).toBe(true);
    expect(
      await projectService.canViewProject(
        { ...tenant.actors.member, isPlatformStaff: true },
        project,
      ),
    ).toBe(true);

    await expect(
      projectService.getProject(outsider, tenant.org.id, "secret"),
    ).rejects.toBeInstanceOf(NotFoundError);

    const listed = await projectService.listProjects(outsider, {
      orgId: tenant.org.id,
      limit: 50,
    });
    expect(listed.items.map((item) => item.project.id)).not.toContain(project.id);
    expect(listed.total).toBe(1);

    const adminListed = await projectService.listProjects(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 50,
    });
    expect(adminListed.total).toBe(2);

    await projectMemberRepo.addProjectMember(tenant.org.id, project.id, outsider.userId);
    expect(await projectService.canViewProject(outsider, project)).toBe(true);
    const after = await projectService.listProjects(outsider, {
      orgId: tenant.org.id,
      limit: 50,
    });
    expect(after.total).toBe(2);

    await projectMemberRepo.removeProjectMember(tenant.org.id, project.id, outsider.userId);
    expect(await projectService.canViewProject(outsider, project)).toBe(false);

    const issue = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, project.id, { title: "Hidden issue" }),
    );

    await expect(
      issueService.getIssue(outsider, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getBoard(outsider, tenant.org.id, project.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.getThread(outsider, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const issues = await issueService.listIssues(outsider, {
      orgId: tenant.org.id,
      limit: 50,
    });
    expect(issues.items.map((row) => row.id)).not.toContain(issue.id);
    expect(issues.total).toBe(0);

    const before = await issueRepo.findIssueById(tenant.org.id, issue.id);
    await expect(
      issueService.updateIssue(outsider, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Leaked",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.changeIssueStatus(outsider, {
        orgId: tenant.org.id,
        issueId: issue.id,
        status: "todo",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.moveIssue(outsider, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toStatus: "todo",
        toIndex: 0,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.assignIssue(outsider, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: outsider.userId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.archiveIssue(outsider, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    const afterIssue = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(afterIssue?.title).toBe(before?.title);
    expect(afterIssue?.status).toBe(before?.status);
    expect(afterIssue?.assigneeId).toBe(before?.assigneeId);
    expect(afterIssue?.archivedAt).toBeNull();

    await expect(
      issueService.createIssue(
        outsider,
        issueInput(tenant.org.id, project.id, { title: "Should not exist" }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.createComment(outsider, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "nope",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const comment = await commentService.createComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "secret note",
      parentId: null,
      mentionedUserIds: [],
    });
    await expect(
      commentService.updateComment(outsider, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "changed",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      commentService.deleteComment(outsider, {
        orgId: tenant.org.id,
        commentId: comment.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

